<script setup>
import {ref,computed,watch} from 'vue'
import Chart from './Chart.vue'
import ModelDiagnostics from './ModelDiagnostics.vue'
import ComparisonAudit from './ComparisonAudit.vue'
import {inEvaluationYear} from './diagnostics.mjs'
import {kindLabel,groups,compatibleComparison} from './workflow.mjs'
const props=defineProps({detail:Object,completed:Array,boot:Object,busy:Boolean,maintenance:Boolean})
const emit=defineEmits(['reuse','replay','state','metadata','stop','save-parameters','experiment'])
const tabs=computed(()=>props.maintenance?[['lake','湖位过程'],['flow','入湖来水'],['evaluation','评价与收支'],['diagnostics','模型诊断'],['comparison','方案核对'],['parameters','本组参数'],['conditions','计算信息']]:[['lake','湖位过程'],['flow','入湖来水'],['balance','水量收支'],['evaluation','效果评价']])
const tab=ref('lake'),compareId=ref(''),other=ref(null),loading=ref(false),failure=ref(''),parameterName=ref(''),evaluationYear=ref('2025')
const result=computed(()=>props.detail?.result)
const number=(v,n=3)=>v==null||!Number.isFinite(Number(v))?'—':Number(v).toLocaleString('zh-CN',{maximumFractionDigits:n})
const compareNote=computed(()=>other.value?compatibleComparison(result.value,other.value.result):'')
const canCompare=computed(()=>other.value?.result&&(!compareNote.value||compareNote.value.startsWith('输入版本不同')))
const rows=computed(()=>{const index=new Map((canCompare.value?other.value.result.daily:[]).map(r=>[r.date,r]));return (result.value?.daily||[]).map(r=>({...r,comparedLake:index.get(r.date)?.lakeLevel,comparedFlow:index.get(r.date)?.duja}))})
const parameterScope=ref('basin')
const displayedParameters=computed(()=>({...result.value?.parameters,...(result.value?.partitionParameters?.[parameterScope.value]||{})}))
const boundaryParameters=computed(()=>result.value?.calibration?props.boot.parameterDefinitions.filter(d=>result.value.calibration.boundaryParameters?.includes(d.key)):[])
const calibrationReview=computed(()=>{const c=result.value?.calibration;if(!c)return [];const notes=[];if(c.reviewFlags?.includes('search-boundary'))notes.push('搜索参数触及边界');if(c.reviewFlags?.includes('search-not-converged'))notes.push('搜索未达到停止判据');if(c.reviewFlags?.includes('insufficient-2025-flow-validation'))notes.push('2025杜加有效流量不足30日');if(c.reviewFlags?.includes('insufficient-2025-lake-validation'))notes.push('2025主站有效湖位不足30日');return notes})
const href=f=>props.detail?.builtin?`/api/model/published-result?id=${props.detail.id}&file=${f}`:`/api/model/export?taskId=${props.detail?.id}&format=${f}`
let sequence=0
watch(()=>props.detail?.id,()=>{compareId.value='';other.value=null;failure.value='';tab.value=props.maintenance&&props.maintenance&&props.detail?.kind==='sensitivity'?'diagnostics':'lake'})
watch(compareId,async id=>{const token=++sequence;other.value=null;failure.value='';loading.value=!!id;if(!id)return;try{const r=await fetch('/api/model/tasks/'+id);const d=await r.json();if(!r.ok)throw Error(d.error);if(token===sequence)other.value=d}catch(e){if(token===sequence)failure.value=e.message}finally{if(token===sequence)loading.value=false}})
const metricYears=computed(()=>Object.keys(result.value?.metrics||{}))
const metricYear=computed(()=>metricYears.value.includes(evaluationYear.value)?evaluationYear.value:(metricYears.value.includes('2024')?'2024':metricYears.value.at(-1)))
const latestMetrics=computed(()=>result.value?.metrics?.[metricYear.value]||null)
const yearRows=computed(()=>inEvaluationYear(rows.value,metricYear.value))
</script>
<template>
 <section v-if="!detail" class="panel result-empty"><span>◈</span><h3>选择计算成果</h3><p>在成果列表中选择记录，查看湖位、来水和水量收支。</p></section>
 <section v-else class="panel calculation-result">
  <div class="panel-title"><h3>{{detail.name||'未命名计算'}}</h3><span class="badge">{{kindLabel(detail.kind)}}</span><button v-if="['running','queued','stopping'].includes(detail.status)" @click="emit('stop',detail.id)">停止任务</button></div>
  <p v-if="maintenance" class="note record-id">{{detail.id}} · {{detail.created_at?.slice(0,19).replace('T',' ')}}</p>
  <div v-if="!result?.daily" class="result-progress"><p>{{detail.message||'等待计算'}}</p><progress :value="detail.progress" max="100"></progress><b>{{number(detail.progress,1)}}%</b><button v-if="detail.request?.parameters" @click="emit('replay')">恢复条件重新计算</button></div>
  <template v-else>
   <div class="record-actions"><button @click="emit('metadata',detail,{favorite:!detail.favorite})">{{detail.favorite?'★ 已收藏':'☆ 收藏'}}</button><button v-if="maintenance" @click="emit('reuse')">采用本组参数</button><button @click="emit('replay')">{{detail.request.schemeId?'重新模拟':'恢复条件'}}</button><button @click="emit('state')">查看状态</button><a class="button" :href="href('daily.csv')">导出日过程</a><details v-if="maintenance" class="more-export"><summary>更多导出</summary><a :href="href('hourly.npz')">逐时数组</a><a :href="href('checkpoint.json')">末状态</a><a :href="href('request.json')">计算条件</a></details></div>
   <div class="form-row"><label>评价年份<select :value="metricYear" @change="evaluationYear=$event.target.value"><option v-for="y in metricYears" :key="y" :value="y">{{y}}</option></select></label></div><div class="result-metrics"><div><span>日湖位RMSE · m</span><b>{{number(latestMetrics?.lake.rmse)}}</b></div><div><span>日湖位MAE · m</span><b>{{number(latestMetrics?.lake.mae)}}</b></div><div><span>湖位匹配天数</span><b>{{number(latestMetrics?.lake.count,0)}}</b></div><div><span>计算起止 · 北京时间</span><strong>{{detail.request.start?.slice(0,16).replace('T',' ')}}<br>{{detail.request.end?.slice(0,16).replace('T',' ')}}</strong></div></div><p v-if="maintenance" class="note">过程图与上方指标对应 {{metricYear}} 年{{latestMetrics?.purpose}}；完整分年流量和湖位评价见“评价与收支”。未率定基线与率定成果均保留实际指标。</p>
   <details v-if="maintenance&&result.calibration" class="calibration-review"><summary>率定状态：候选方案，尚未业务定型</summary><p v-if="maintenance" class="note">仅用于参数比较和历史验证。<span v-if="calibrationReview.length">需复核：{{calibrationReview.join('；')}}。</span><span v-if="boundaryParameters.length">触边参数：{{boundaryParameters.map(d=>d.label+' = '+(result.partitionParameters?.[result.calibration.calibrationPartition]?.[d.key]??result.parameters[d.key])).join('；')}}。</span><span v-if="result.calibration.validationCounts">2025验证样本：流量{{result.calibration.validationCounts['2025FlowDays']}}日、湖位{{result.calibration.validationCounts['2025LakeDays']}}日。</span></p></details><nav class="workspace-tabs result-tabs" aria-label="成果详情"><button v-for="t in tabs" :key="t[0]" :class="{active:tab===t[0]}" @click="tab=t[0]">{{t[1]}}</button></nav>
   <div v-if="['lake','flow','comparison'].includes(tab)" class="comparison-row"><label>叠加成果<select v-model="compareId"><option value="">不叠加</option><option v-for="t in completed.filter(t=>t.id!==detail.id&&!t.trashed)" :key="t.id" :value="t.id">{{t.name||t.id}}</option></select></label><span>{{loading?'读取比较过程…':failure||compareNote}}</span></div>
   <template v-if="tab==='lake'"><p v-if="yearRows.every(r=>r.lakeLevel==null)" class="note warning">所选时段暂无湖位过程</p><Chart :rows="yearRows" :series="[{key:'lakeLevel',label:'模拟湖位'},{key:'observedLevel',label:'主站实测'},...(canCompare?[{key:'comparedLake',label:'对比湖位'}]:[])]" unit="m" :context="detail.id+':result-lake:'+metricYear"/><p v-if="maintenance" class="note">每个可靠观测窗口只用首个观测初始化，之后独立演算；窗口冰情尚未独立核验，四岸水位分别查询。</p></template>
   <template v-if="tab==='flow'"><Chart :rows="yearRows" :series="[{key:'duja',label:'杜加模拟'},{key:'observedFlow',label:'杜加实测'},{key:'total',label:'总入湖流量'},...(canCompare?[{key:'comparedFlow',label:'对比杜加'}]:[])]" unit="m³/s" :context="detail.id+':result-flow:'+metricYear"/><Chart :rows="yearRows" :series="[{key:'zajia',label:'扎加藏布'},{key:'zagen',label:'扎根藏布'},{key:'boqu',label:'波曲藏布'},{key:'ali',label:'阿里藏布'},{key:'fringe',label:'湖周来水'}]" unit="m³/s" :context="detail.id+':result-rivers:'+metricYear"/><p v-if="maintenance" class="note">杜加是内部控制断面，不重复计入总入湖流量。其余河流尚未独立验证。</p></template>
   <template v-if="tab==='balance'"><Chart :rows="yearRows" :series="[{key:'lakeInflowM3',label:'入湖水量',type:'bar'},{key:'lakePrecipitationM3',label:'湖面降水',type:'bar'},{key:'lakeEvaporationM3',label:'湖面蒸发',type:'bar'},{key:'lakeDeltaVolumeM3',label:'蓄水变化'}]" unit="m³/d" :context="detail.id+':result-balance:'+metricYear"/></template>
   <template v-if="tab==='evaluation'"><div class="table-wrap"><table><thead><tr><th>年份</th><th>流量天数</th><th>NSE / KGE</th><th>PBIAS %</th><th>湖位天数</th><th>RMSE / MAE m</th><th>偏差 m</th></tr></thead><tbody><tr v-for="(m,y) in result.metrics" :key="y"><td>{{y}}</td><td>{{m.flow.count}}</td><td>{{number(m.flow.nse)}} / {{number(m.flow.kge)}}</td><td>{{number(m.flow.pbias)}}</td><td>{{m.lake.count}}</td><td>{{number(m.lake.rmse)}} / {{number(m.lake.mae)}}</td><td>{{number(m.lake.bias)}}</td></tr></tbody></table></div><Chart v-if="maintenance" :rows="yearRows" :series="[{key:'lakeRainMm',label:'湖面降水',type:'bar'},{key:'lakeEvaporationMm',label:'湖面蒸发',type:'bar'},{key:'snowmeltMm',label:'融雪补给'},{key:'icemeltMm',label:'融冰补给'}]" unit="mm/d" :context="detail.id+':result-evaluation:'+metricYear"/><p v-if="maintenance" class="note">湖面降水和蒸发按湖面积折算，融雪和融冰为陆面平均水深，仅比较过程时序，不能直接相加。融水已包含在产汇流中，不与总入湖流量再次相加。地下水净交换与外流暂按零。</p><p v-if="maintenance&&result.calibration" class="note">搜索 {{result.calibration.evaluations}} 次 · {{result.calibration.termination==='converged'?'达到收敛条件':result.calibration.termination==='proposal-limit'?'达到候选约束上限':'预算耗尽'}} · 仅使用2024观测</p><details v-if="maintenance"><summary>水量守恒诊断与假设</summary><pre>{{JSON.stringify(result.diagnostics,null,2)}}</pre></details></template>
   <ComparisonAudit v-if="tab==='comparison'" :current="result" :other="other?.result" :current-request="detail.request" :other-request="other?.request" :year="metricYear" :definitions="boot.parameterDefinitions"/><ModelDiagnostics v-if="tab==='diagnostics'" :result="result" :context="detail.id+':diagnostics'" @experiment="emit('experiment',$event)"/>
   <template v-if="tab==='parameters'"><div class="form-row"><label>参数范围<select v-model="parameterScope"><option value="basin">流域背景参数</option><option v-for="(_,key) in result.partitionParameters||{}" :key="key" :value="key">{{key==='duja'?'杜加控制区':key}}</option></select></label></div><div v-for="g in groups" :key="g.key"><h4>{{g.label}}</h4><div class="frozen-parameters"><div v-for="d in boot.parameterDefinitions.filter(d=>d.group===g.key)" :key="d.key"><span>{{d.label}} <small>{{d.key}}</small></span><b>{{displayedParameters[d.key]??'本版本未配置'}} {{d.unit}}</b></div></div></div><div class="form-row"><label class="grow">保存成果参数<input v-model="parameterName" placeholder="参数名称"></label><button :disabled="!parameterName.trim()||busy" @click="emit('save-parameters',parameterName,result.parameters,detail.id)">保存到参数库</button></div></template>
   <template v-if="tab==='conditions'"><dl><dt>真实输入版本</dt><dd>{{result.inputId}}</dd><dt>空间版本</dt><dd>{{result.spatialVersion}}</dd><dt>计算起止</dt><dd>{{detail.request.start}} — {{detail.request.end}}</dd><dt>来源状态</dt><dd>{{detail.request.stateId||'新起算'}}</dd><dt>汇流结构</dt><dd>{{result.routingMode==='source-separated'?'分水源调蓄 + 河道汇流':'原单库汇流'}}</dd><dt>模型实现</dt><dd>{{result.identity?.modelImplementation}}</dd></dl><details><summary>冻结计算条件</summary><pre>{{JSON.stringify(detail.request,null,2)}}</pre></details></template>
   <details class="result-organize"><summary>成果命名与整理</summary><div class="form-row"><label class="grow">名称<input :value="detail.name" @change="emit('metadata',detail,{name:$event.target.value})"></label><label class="grow">备注<input :value="detail.notes" @change="emit('metadata',detail,{notes:$event.target.value})"></label><label>分组<input :value="detail.collection" @change="emit('metadata',detail,{collection:$event.target.value})"></label></div></details>
  </template>
 </section>
</template>
